def extract_receipt_fields(document_s3_path: str) -> ReceiptDocument:
    """Extracts merchant, tax, total, and items from a receipt using AWS Textract AnalyzeExpense.

    Args:
        document_s3_path: S3 path to the receipt document (e.g., "s3://bucket-name/path/to/receipt.pdf")

    Returns:
        A ReceiptDocument object containing the extracted fields and raw Textract output.
    """
    textract_client = get_aws_textract_client()

    bucket_name = document_s3_path.split('/')[2]
    object_name = '/'.join(document_s3_path.split('/')[3:])

    response = textract_client.analyze_expense(
        Document={
            'S3Object': {
                'Bucket': bucket_name,
                'Name': object_name
            }
        }
    )

    extracted_merchant = None
    extracted_date = None
    extracted_total = None
    extracted_tax = None
    extracted_currency = None
    extracted_line_items: List[LineItem] = []

    # AnalyzeExpense response structure is different from AnalyzeDocument
    # It provides a list of ExpenseDocuments, usually one per receipt image
    for expense_doc in response.get('ExpenseDocuments', []):
        # Summary fields
        summary_fields = expense_doc.get('SummaryFields', [])
        for field in summary_fields:
            field_type = field.get('Type', {}).get('Text')
            field_value = field.get('ValueDetection', {}).get('Text')
            field_confidence = field.get('ValueDetection', {}).get('Confidence')

            if field_type == 'MERCHANT_NAME':
                extracted_merchant = field_value
            elif field_type == 'DATE':
                extracted_date = field_value
            elif field_type == 'TOTAL':
                try:
                    extracted_total = float(field_value)
                    if field.get('ValueDetection', {}).get('Currency'):
                        extracted_currency = field.get('ValueDetection', {}).get('Currency')
                except (ValueError, TypeError):
                    pass
            elif field_type == 'TAX':
                try:
                    extracted_tax = float(field_value)
                except (ValueError, TypeError):
                    pass

        # Line item fields
        line_item_groups = expense_doc.get('LineItemGroups', [])
        for group in line_item_groups:
            for item in group.get('LineItems', []):
                line_item_fields: List[LineItemField] = []
                for field in item.get('LineItemExpenseFields', []):
                    field_type = field.get('Type', {}).get('Text')
                    field_value = field.get('ValueDetection', {}).get('Text')
                    field_confidence = field.get('ValueDetection', {}).get('Confidence')
                    line_item_fields.append(LineItemField(name=field_type, value=field_value, confidence=field_confidence))
                extracted_line_items.append(LineItem(fields=line_item_fields))

    return ReceiptDocument(
        merchant_name=extracted_merchant,
        transaction_date=extracted_date,
        total_amount=extracted_total,
        tax_amount=extracted_tax,
        currency=extracted_currency,
        line_items=extracted_line_items,
        raw_textract_output=response
    )

from typing import Union, Dict, Any
from document_models import InvoiceDocument, ReceiptDocument, NormalizedExpense

def normalize_expense(document: Union[InvoiceDocument, ReceiptDocument]) -> NormalizedExpense:
    """Normalizes extracted invoice or receipt fields into a standard JSON schema (NormalizedExpense).

    Args:
        document: An InvoiceDocument or ReceiptDocument object.

    Returns:
        A NormalizedExpense object.
    """
    confidence_scores: Dict[str, float] = {}

    if isinstance(document, InvoiceDocument):
        document_type = "invoice"
        vendor_merchant_name = document.vendor_name
        transaction_date = document.invoice_date
        total_amount = document.total_amount
        currency = document.currency
        tax_amount = None
        line_items = []

        if document.raw_textract_output:
            # Example: Extract confidence for vendor name from raw Textract output
            # This is a simplified approach, a real implementation would traverse the blocks
            # to find confidence of specific fields.
            for block in document.raw_textract_output.get('Blocks', []):
                if block['BlockType'] == 'WORD' and document.vendor_name and document.vendor_name in block['Text']:
                    confidence_scores['vendor_name'] = block['Confidence']
                    break
            # More confidence scores can be added here for date, total, etc.

        for item in document.line_items:
            line_item_data = {}
            for field in item.fields:
                if field.name and field.value:
                    line_item_data[field.name.lower().replace(' ', '_')] = field.value
                    if field.confidence:
                        confidence_scores[f'line_item_{field.name.lower().replace(' ', '_')}_confidence'] = field.confidence
            if line_item_data:
                line_items.append(line_item_data)


    elif isinstance(document, ReceiptDocument):
        document_type = "receipt"
        vendor_merchant_name = document.merchant_name
        transaction_date = document.transaction_date
        total_amount = document.total_amount
        currency = document.currency
        tax_amount = document.tax_amount
        line_items = []

        if document.raw_textract_output:
            # Example: Extract confidence for merchant name from raw Textract output
            for expense_doc in document.raw_textract_output.get('ExpenseDocuments', [])[:1]: # Take the first one
                for field in expense_doc.get('SummaryFields', []):
                    field_type = field.get('Type', {}).get('Text')
                    if field_type == 'MERCHANT_NAME' and field.get('ValueDetection', {}).get('Confidence') is not None:
                        confidence_scores['merchant_name'] = field['ValueDetection']['Confidence']
                    elif field_type == 'TOTAL' and field.get('ValueDetection', {}).get('Confidence') is not None:
                        confidence_scores['total_amount'] = field['ValueDetection']['Confidence']
                    elif field_type == 'TAX' and field.get('ValueDetection', {}).get('Confidence') is not None:
                        confidence_scores['tax_amount'] = field['ValueDetection']['Confidence']
                    elif field_type == 'DATE' and field.get('ValueDetection', {}).get('Confidence') is not None:
                        confidence_scores['transaction_date'] = field['ValueDetection']['Confidence']

                for item_group in expense_doc.get('LineItemGroups', [])[:1]:
                    for item in item_group.get('LineItems', [])[:1]:
                        for field in item.get('LineItemExpenseFields', []):
                            if field.get('ValueDetection', {}).get('Confidence') is not None:
                                confidence_scores[f'line_item_{field.get('Type', {}).get('Text', '').lower().replace(' ', '_')}_confidence'] = field['ValueDetection']['Confidence']

        for item in document.line_items:
            line_item_data = {}
            for field in item.fields:
                if field.name and field.value:
                    line_item_data[field.name.lower().replace(' ', '_')] = field.value
                    if field.confidence:
                        confidence_scores[f'line_item_{field.name.lower().replace(' ', '_')}_confidence'] = field.confidence
            if line_item_data:
                line_items.append(line_item_data)

    else:
        raise ValueError("Unsupported document type.")

    return NormalizedExpense(
        document_type=document_type,
        vendor_merchant_name=vendor_merchant_name,
        transaction_date=transaction_date,
        total_amount=total_amount,
        currency=currency,
        tax_amount=tax_amount,
        line_items=line_items,
        confidence_scores=confidence_scores,
        original_extracted_data=document.raw_textract_output if document.raw_textract_output else {}
    )

from typing import List
from document_models import NormalizedExpense

def validate_document_fields(expense: NormalizedExpense, required_fields: List[str], min_confidence: float = 0.8) -> Dict[str, Any]:
    """Validates required structured fields and confidence scores of a NormalizedExpense.

    Args:
        expense: A NormalizedExpense object.
        required_fields: A list of field names that must be present (e.g., ['vendor_merchant_name', 'total_amount'])
        min_confidence: Minimum required confidence score for fields.

    Returns:
        A dictionary with validation results, including missing fields and low confidence fields.
    """
    validation_results = {
        "is_valid": True,
        "missing_fields": [],
        "low_confidence_fields": []
    }

    # Validate required fields presence
    for field in required_fields:
        if not getattr(expense, field, None):
            validation_results["is_valid"] = False
            validation_results["missing_fields"].append(field)

    # Validate confidence scores
    for field_name, confidence in expense.confidence_scores.items():
        if confidence < min_confidence:
            validation_results["is_valid"] = False
            validation_results["low_confidence_fields"].append({
                "field": field_name,
                "confidence": confidence
            })

    return validation_results

import os
from typing import Dict, Any
from document_client import get_google_vertex_ai_model
from document_models import NormalizedExpense

def summarize_invoice_fields(expense: NormalizedExpense) -> Dict[str, Any]:
    """Summarizes extracted invoice fields using Google Cloud Vertex AI (Gemini model).

    Args:
        expense: A NormalizedExpense object representing the invoice data.

    Returns:
        A dictionary containing the summary and the raw model response.
    """
    project_id = os.environ.get('GCP_PROJECT_ID')
    location = os.environ.get('GCP_LOCATION', 'us-central1')
    model_name = os.environ.get('GCP_GEMINI_MODEL', 'gemini-pro')

    if not project_id:
        raise ValueError("GCP_PROJECT_ID environment variable not set.")

    model = get_google_vertex_ai_model(project_id, location, model_name)

    invoice_data_str = f"""
    Document Type: {expense.document_type}
    Vendor/Merchant: {expense.vendor_merchant_name}
    Transaction Date: {expense.transaction_date}
    Total Amount: {expense.total_amount} {expense.currency}
    Tax Amount: {expense.tax_amount}
    Line Items: {expense.line_items}
    """

    prompt = f"""Summarize the following expense document data. Focus on key financial details and vendor information. 
    {invoice_data_str}
    """

    response = model.generate_content(prompt)

    summary_text = "No summary generated." # Default in case response doesn't have text
    if response.candidates:
        for candidate in response.candidates:
            if hasattr(candidate, 'content') and hasattr(candidate.content, 'parts'):
                for part in candidate.content.parts:
                    if hasattr(part, 'text'):
                        summary_text = part.text
                        break
            if summary_text != "No summary generated.":
                break

    return {
        "summary": summary_text,
        "raw_model_response": response.to_dict() if hasattr(response, 'to_dict') else str(response)
    }

import os
from typing import Dict, Any
from document_client import get_google_safety_model

def moderate_vendor_notes(text_to_moderate: str) -> Dict[str, Any]:
    """Moderates vendor notes or memo fields using Google Cloud Vertex AI with safety attributes.

    Args:
        text_to_moderate: The text from vendor notes or memo fields.

    Returns:
        A dictionary containing the safety attribute scores and the raw model response.
    """
    project_id = os.environ.get('GCP_PROJECT_ID')
    location = os.environ.get('GCP_LOCATION', 'us-central1')
    model_name = os.environ.get('GCP_SAFETY_MODEL', 'gemini-pro') # Using gemini-pro for safety checks

    if not project_id:
        raise ValueError("GCP_PROJECT_ID environment variable not set.")

    model = get_google_safety_model(project_id, location, model_name)

    response = model.generate_content(
        text_to_moderate,
        safety_settings=[
            {
                "category": "HARM_CATEGORY_HARASSMENT",
                "threshold": "BLOCK_MEDIUM_AND_ABOVE"
            },
            {
                "category": "HARM_CATEGORY_HATE_SPEECH",
                "threshold": "BLOCK_MEDIUM_AND_ABOVE"
            },
            {
                "category": "HARM_CATEGORY_SEXUALLY_EXPLICIT",
                "threshold": "BLOCK_MEDIUM_AND_ABOVE"
            },
            {
                "category": "HARM_CATEGORY_DANGEROUS_CONTENT",
                "threshold": "BLOCK_MEDIUM_AND_ABOVE"
            },
        ]
    )

    safety_attributes = {"blocked": False, "scores": {}}

    # Check if the content was blocked
    if response.prompt_feedback and response.prompt_feedback.block_reason: # Check for a block reason
        safety_attributes["blocked"] = True
        safety_attributes["block_reason"] = response.prompt_feedback.block_reason.name

    # Extract safety ratings if available
    if response.candidates:
        for candidate in response.candidates:
            if hasattr(candidate, 'safety_ratings'):
                for rating in candidate.safety_ratings:
                    category = rating.category.name.replace("HARM_CATEGORY_", "").lower()
                    safety_attributes["scores"][category] = rating.probability.name

    return {
        "safety_attributes": safety_attributes,
        "raw_model_response": response.to_dict() if hasattr(response, 'to_dict') else str(response)
    }
